-- Rows the app itself writes already pass these; a restored or hand-edited file may not.
-- Triggers rather than rebuilt tables with CHECKs, so rows already stored are never re-judged and an
-- upgrade cannot fail on one.
CREATE TRIGGER debts_valid_insert BEFORE INSERT ON debts WHEN NOT (length(trim(NEW.name)) BETWEEN 1 AND 80 AND length(NEW.currency)=3 AND typeof(NEW.balance_minor)='integer' AND NEW.balance_minor BETWEEN 0 AND 9007199254740991 AND typeof(NEW.minimum_minor)='integer' AND NEW.minimum_minor BETWEEN 0 AND 9007199254740991 AND typeof(NEW.annual_rate_bp)='integer' AND NEW.annual_rate_bp BETWEEN 0 AND 100000 AND (NEW.due_day IS NULL OR typeof(NEW.due_day)='integer') AND (length(NEW.opened_at)=10 AND NEW.opened_at GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]') AND (NEW.closed_at IS NULL OR (length(NEW.closed_at)=10 AND NEW.closed_at GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'))) BEGIN SELECT RAISE(ABORT, 'That debt row is not valid.'); END;
CREATE TRIGGER debts_valid_update BEFORE UPDATE ON debts WHEN NOT (length(trim(NEW.name)) BETWEEN 1 AND 80 AND length(NEW.currency)=3 AND typeof(NEW.balance_minor)='integer' AND NEW.balance_minor BETWEEN 0 AND 9007199254740991 AND typeof(NEW.minimum_minor)='integer' AND NEW.minimum_minor BETWEEN 0 AND 9007199254740991 AND typeof(NEW.annual_rate_bp)='integer' AND NEW.annual_rate_bp BETWEEN 0 AND 100000 AND (NEW.due_day IS NULL OR typeof(NEW.due_day)='integer') AND (length(NEW.opened_at)=10 AND NEW.opened_at GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]') AND (NEW.closed_at IS NULL OR (length(NEW.closed_at)=10 AND NEW.closed_at GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'))) BEGIN SELECT RAISE(ABORT, 'That debt row is not valid.'); END;
CREATE TRIGGER ious_valid_insert BEFORE INSERT ON ious WHEN NOT (length(trim(NEW.person)) BETWEEN 1 AND 80 AND length(trim(NEW.reason)) BETWEEN 1 AND 200 AND length(NEW.currency)=3 AND typeof(NEW.amount_minor)='integer' AND NEW.amount_minor BETWEEN 1 AND 9007199254740991 AND (length(NEW.occurred_on)=10 AND NEW.occurred_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]') AND (NEW.settled_at IS NULL OR (length(NEW.settled_at)=10 AND NEW.settled_at GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'))) BEGIN SELECT RAISE(ABORT, 'That IOU row is not valid.'); END;
CREATE TRIGGER ious_valid_update BEFORE UPDATE ON ious WHEN NOT (length(trim(NEW.person)) BETWEEN 1 AND 80 AND length(trim(NEW.reason)) BETWEEN 1 AND 200 AND length(NEW.currency)=3 AND typeof(NEW.amount_minor)='integer' AND NEW.amount_minor BETWEEN 1 AND 9007199254740991 AND (length(NEW.occurred_on)=10 AND NEW.occurred_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]') AND (NEW.settled_at IS NULL OR (length(NEW.settled_at)=10 AND NEW.settled_at GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'))) BEGIN SELECT RAISE(ABORT, 'That IOU row is not valid.'); END;
